async function batchLoadUsers(ids) {
  // ids: [7, 3, 9, 3]
  const rows = await db.user.findMany({ where: { id: { in: ids } } });
  // DB returns rows in arbitrary (index/physical) order,
  // and drops ids that don't exist.
  return rows; // <-- returned straight from the DB
}

function dbFindUsers(ids) {
  const ALL = { 3: { id: 3, name: 'C' }, 7: { id: 7, name: 'G' } };
  // returns matching rows in id-ascending order, omits misses
  return ids.filter(id => ALL[id]).map(id => ALL[id]).sort((a, b) => a.id - b.id);
}
function batchUsers(keys) {
  const rows = dbFindUsers(keys);
  // returned straight from the DB, in DB order
  return rows;
}

